package com.hbm.entity.missile;
import api.hbm.entity.IRadarDetectableNT;import com.hbm.bomb.nuclear.LegacyVector;import com.hbm.entity.LegacyTrackingRange;import com.hbm.entity.projectile.EntityThrowableInterp;import com.hbm.explosion.ExplosionLarge;import com.hbm.missile.completion.MissileContent;import com.hbm.radar.*;import com.hbm.weapon.specialvehicle.VehicleShockEffects;import java.util.*;import java.util.function.Consumer;import net.minecraft.nbt.CompoundTag;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.Mth;import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import net.neoforged.neoforge.common.world.chunk.TicketController;
/** Original dedicated interceptor: forty-tick activation, predictive interception and NT radar cache acquisition. */
public final class EntityMissileAntiBallistic extends EntityThrowableInterp implements IRadarDetectableNT,api.hbm.entity.IRadarDetectable,LegacyTrackingRange {
 public static final TicketController TICKETS=new TicketController(ResourceLocation.parse("hbm:missile_abm"));public static Consumer<Contrail> contrails=ignored->{};public record Contrail(Level level,double x,double y,double z){}public Entity tracking;public double velocity;protected int activationTimer;public static double baseSpeed=1.5D;public int trackingRange=1000;private final Set<ChunkPos> loaded=new LinkedHashSet<>();private ChunkPos center;
 public EntityMissileAntiBallistic(EntityType<?> type,Level level){super(type,level);setDeltaMovement(0,baseSpeed,0);noCulling=true;}public EntityMissileAntiBallistic(Level level){this(MissileContent.type("missile_anti_ballistic"),level);}@Override protected double motionMult(){return velocity;}@Override public boolean doesImpactEntities(){return false;}
 @Override public void tick(){super.tick();if(!level().isClientSide){if(velocity<6)velocity+=.1;if(activationTimer<40){activationTimer++;var m=getDeltaMovement();setDeltaMovement(m.x,baseSpeed,m.z);}else{var before=tracking;if(tracking==null||!tracking.isAlive())targetMissile();if(before==null&&tracking!=null)VehicleShockEffects.shock(level(),getX(),getY(),getZ(),24,3);if(tracking!=null&&tracking.isAlive())aimAtTarget();else if(tickCount>600)discard();}loadNeighboringChunks(Mth.floor(getX()/16),Mth.floor(getZ()/16));if(getY()>2000&&(tracking==null||!tracking.isAlive()))discard();}else{var motion=getDeltaMovement().normalize();contrails.accept(new Contrail(level(),getX()-motion.x,getY()-motion.y,getZ()-motion.z));}var motion=getDeltaMovement();float horizontal=(float)Math.sqrt(motion.x*motion.x+motion.z*motion.z);setYRot((float)(Math.atan2(motion.x,motion.z)*180D/Math.PI));setXRot((float)(Math.atan2(motion.y,horizontal)*180D/Math.PI)-90);while(getXRot()-xRotO< -180)xRotO-=360;while(getXRot()-xRotO>=180)xRotO+=360;while(getYRot()-yRotO< -180)yRotO-=360;while(getYRot()-yRotO>=180)yRotO+=360;}
 /** Source never narrows dist after a match: the last eligible cache entry under1000 is retained. */
 protected void targetMissile(){Entity closest=null;double dist=1000;for(var candidate:RadarTargetCache.matchingEntities()){if(candidate.level()!=level()||!(candidate instanceof EntityMissileBaseNT)||candidate instanceof StealthRadarExempt)continue;var delta=LegacyVector.createVectorHelper(candidate.getX()-getX(),candidate.getY()-getY(),candidate.getZ()-getZ());if(delta.lengthVector()<dist)closest=candidate;}tracking=closest;}
 protected void aimAtTarget(){var delta=LegacyVector.createVectorHelper(tracking.getX()-getX(),tracking.getY()-getY(),tracking.getZ()-getZ());double intercept=delta.lengthVector()/(baseSpeed*velocity);var predicted=LegacyVector.createVectorHelper(tracking.getX()+(tracking.getX()-tracking.xo)*intercept,tracking.getY()+(tracking.getY()-tracking.yo)*intercept,tracking.getZ()+(tracking.getZ()-tracking.zo)*intercept);var motion=LegacyVector.createVectorHelper(predicted.xCoord-getX(),predicted.yCoord-getY(),predicted.zCoord-getZ()).normalize();if(delta.lengthVector()<10&&activationTimer>=40){discard();ExplosionLarge.explode(level(),getX(),getY(),getZ(),15,true,false,false);}setDeltaMovement(motion.xCoord*baseSpeed,motion.yCoord*baseSpeed,motion.zCoord*baseSpeed);}
 @Override protected void onImpact(HitResult hit){if(activationTimer>=40){discard();ExplosionLarge.explode(level(),getX(),getY(),getZ(),20,true,false,false);}}@Override public double getGravityVelocity(){return 0;}@Override protected float getAirDrag(){return 1;}@Override protected float getWaterDrag(){return 1;}
 @Override protected void readAdditionalSaveData(CompoundTag tag){super.readAdditionalSaveData(tag);velocity=tag.getDouble("veloc");}@Override protected void addAdditionalSaveData(CompoundTag tag){super.addAdditionalSaveData(tag);tag.putDouble("veloc",velocity);}
 @Override public void onAddedToLevel(){super.onAddedToLevel();loadNeighboringChunks(Mth.floor(getX()/16),Mth.floor(getZ()/16));}public void loadNeighboringChunks(int x,int z){if(!(level() instanceof ServerLevel server)||isRemoved())return;var next=new ChunkPos(x,z);if(next.equals(center))return;for(var chunk:loaded)TICKETS.forceChunk(server,this,chunk.x,chunk.z,false,true);loaded.clear();for(int i=-1;i<=1;i++)for(int j=-1;j<=1;j++){var chunk=new ChunkPos(x+i,z+j);loaded.add(chunk);TICKETS.forceChunk(server,this,chunk.x,chunk.z,true,true);}center=next;}public void clearChunkLoader(){if(level() instanceof ServerLevel server)for(var chunk:loaded)TICKETS.forceChunk(server,this,chunk.x,chunk.z,false,true);loaded.clear();center=null;}@Override public void remove(RemovalReason reason){if(reason.shouldDestroy()||reason==RemovalReason.CHANGED_DIMENSION)clearChunkLoader();super.remove(reason);}
 @Override public api.hbm.entity.IRadarDetectable.RadarTargetType getTargetType(){return api.hbm.entity.IRadarDetectable.RadarTargetType.MISSILE_AB;}
 @Override public boolean shouldRenderAtSqrDistance(double distance){return true;}@Override public int legacyTrackingRange(){return trackingRange;}@Override public String getUnlocalizedName(){return "radar.target.abm";}@Override public int getBlipLevel(){return TIER_AB;}@Override public boolean canBeSeenBy(Object radar){return true;}@Override public boolean paramsApplicable(RadarScanParams params){return params.scanMissiles;}@Override public boolean suppliesRedstone(RadarScanParams params){return false;}
}
